namespace coincide::background_host {
struct Handle {HANDLE value{INVALID_HANDLE_VALUE};Handle()=default;explicit Handle(HANDLE handle):value(handle){}~Handle(){reset();}Handle(const Handle&)=delete;Handle& operator=(const Handle&)=delete;Handle(Handle&& other)noexcept:value(std::exchange(other.value,INVALID_HANDLE_VALUE)){}Handle& operator=(Handle&& other)noexcept{if(this!=&other){reset();value=std::exchange(other.value,INVALID_HANDLE_VALUE);}return*this;}void reset(HANDLE next=INVALID_HANDLE_VALUE){if(value&&value!=INVALID_HANDLE_VALUE)CloseHandle(value);value=next;}explicit operator bool()const{return value&&value!=INVALID_HANDLE_VALUE;}};
inline std::wstring user_sid(HANDLE process=GetCurrentProcess()){HANDLE raw{};if(!OpenProcessToken(process,TOKEN_QUERY,&raw))winrt::throw_last_error();Handle token(raw);DWORD bytes{};GetTokenInformation(raw,TokenUser,nullptr,0,&bytes);if(!bytes||bytes>65536)throw std::runtime_error("Could not identify background-host user");std::vector<BYTE> buffer(bytes);if(!GetTokenInformation(raw,TokenUser,buffer.data(),bytes,&bytes))winrt::throw_last_error();PWSTR text{};if(!ConvertSidToStringSidW(reinterpret_cast<TOKEN_USER*>(buffer.data())->User.Sid,&text))winrt::throw_last_error();const std::wstring value(text);LocalFree(text);return value;}
struct UserSecurity {
    PSECURITY_DESCRIPTOR descriptor{};SECURITY_ATTRIBUTES attributes{sizeof(SECURITY_ATTRIBUTES),nullptr,FALSE};
    explicit UserSecurity(const std::wstring& sid,bool directory=false){const auto sddl=L"O:"+sid+L"D:P(A;"+(directory?std::wstring(L"OICI"):std::wstring{})+L";GA;;;"+sid+L")";if(!ConvertStringSecurityDescriptorToSecurityDescriptorW(sddl.c_str(),SDDL_REVISION_1,&descriptor,nullptr))winrt::throw_last_error();attributes.lpSecurityDescriptor=descriptor;}
    ~UserSecurity(){if(descriptor)LocalFree(descriptor);}UserSecurity(const UserSecurity&)=delete;UserSecurity& operator=(const UserSecurity&)=delete;
};
inline void verify_security(HANDLE object,const std::wstring& sid,SE_OBJECT_TYPE kind=SE_KERNEL_OBJECT){PSID expected{};if(!ConvertStringSidToSidW(sid.c_str(),&expected))winrt::throw_last_error();struct Free{void* value;~Free(){LocalFree(value);}}free_sid{expected};PSID owner{};PACL acl{};PSECURITY_DESCRIPTOR descriptor{};const auto code=GetSecurityInfo(object,kind,OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION,&owner,nullptr,&acl,nullptr,&descriptor);if(code!=ERROR_SUCCESS)throw std::runtime_error("Could not authenticate background-host object permissions");Free free_descriptor{descriptor};if(!owner||!EqualSid(owner,expected)||!acl||acl->AceCount!=1)throw std::runtime_error("Background-host objects must be accessible only to their Windows user");void* raw{};if(!GetAce(acl,0,&raw))winrt::throw_last_error();const auto ace=static_cast<ACCESS_ALLOWED_ACE*>(raw);if(ace->Header.AceType!=ACCESS_ALLOWED_ACE_TYPE||!EqualSid(reinterpret_cast<PSID>(&ace->SidStart),expected))throw std::runtime_error("Unexpected background-host object permissions");}
class Scope {
    Handle root_;FILE_ID_INFO identity_{};std::filesystem::path physical_;std::wstring sid_,pipe_,mutex_;std::string id_;
    static std::string identity(const FILE_ID_INFO& info){std::string out=std::to_string(info.VolumeSerialNumber)+":";constexpr char hex[]="0123456789abcdef";for(const auto byte:info.FileId.Identifier){out+=hex[byte>>4];out+=hex[byte&15];}return out;}
public:
    explicit Scope(const std::filesystem::path& directory){if(!directory.is_absolute())throw std::invalid_argument("Background host requires an existing local app data folder");root_.reset(CreateFileW(directory.c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS,nullptr));std::array<wchar_t,32768> final{};BY_HANDLE_FILE_INFORMATION attributes{};const auto count=root_?GetFinalPathNameByHandleW(root_.value,final.data(),static_cast<DWORD>(final.size()),FILE_NAME_NORMALIZED|VOLUME_NAME_DOS):0;
        if(!root_||!GetFileInformationByHandleEx(root_.value,FileIdInfo,&identity_,sizeof(identity_))||!GetFileInformationByHandle(root_.value,&attributes)||!(attributes.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY)||!count||count>=final.size())throw std::runtime_error("Could not bind the physical background-host data folder");std::wstring path(final.data(),count);if(path.starts_with(L"\\\\?\\"))path.erase(0,4);physical_=path;if(!local_file::local_path(physical_))throw std::invalid_argument("Background host data must resolve to local storage");sid_=user_sid();id_=local_file::sha256(winrt::to_string(sid_)+":"+identity(identity_));pipe_=L"\\\\.\\pipe\\Coincide-Host-"+std::wstring(winrt::to_hstring(id_));mutex_=L"Global\\Coincide-Host-"+std::wstring(winrt::to_hstring(id_));}
    const std::filesystem::path& directory()const{return physical_;}const std::wstring& sid()const{return sid_;}const std::wstring& pipe()const{return pipe_;}const std::wstring& mutex()const{return mutex_;}const std::string& id()const{return id_;}
    std::filesystem::path ledger_directory()const{return physical_/L"agent-host-windows";}
    void verify()const{Scope fresh(physical_);if(fresh.id_!=id_)throw std::runtime_error("The physical app data folder changed; background work was paused");}
    void prepare_private_directory()const{verify();const auto path=ledger_directory();if(local_file::reparse(path))throw std::runtime_error("The private host ledger cannot be a link or junction");UserSecurity security(sid_,true);if(!CreateDirectoryW(path.c_str(),&security.attributes)&&GetLastError()!=ERROR_ALREADY_EXISTS)throw std::runtime_error("Could not create the private runtime ledger folder");Handle folder(CreateFileW(path.c_str(),READ_CONTROL|FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,nullptr));BY_HANDLE_FILE_INFORMATION info{};if(!folder||!GetFileInformationByHandle(folder.value,&info)||(info.dwFileAttributes&FILE_ATTRIBUTE_REPARSE_POINT))throw std::runtime_error("The host ledger folder is unavailable or linked");verify_security(folder.value,sid_,SE_FILE_OBJECT);}
};
enum class Ownership{free,owned,unavailable};
// Read-only preflight. An owned OR unavailable host must never trigger a second in-app
// runtime merely because IPC cannot be reached. No directory, lock or service is created.
inline Ownership ownership(const Scope& scope)noexcept{try{scope.verify();Handle mutex(OpenMutexW(SYNCHRONIZE|MUTEX_MODIFY_STATE|READ_CONTROL,FALSE,scope.mutex().c_str()));if(mutex){verify_security(mutex.value,scope.sid());const auto status=WaitForSingleObject(mutex.value,0);if(status==WAIT_TIMEOUT)return Ownership::owned;if(status!=WAIT_OBJECT_0&&status!=WAIT_ABANDONED)return Ownership::unavailable;ReleaseMutex(mutex.value);}else if(GetLastError()!=ERROR_FILE_NOT_FOUND)return Ownership::unavailable;const auto lock=scope.ledger_directory()/L"host.lock";if(!std::filesystem::exists(lock))return Ownership::free;if(local_file::has_reparse(lock))return Ownership::unavailable;Handle file(CreateFileW(lock.c_str(),GENERIC_READ|GENERIC_WRITE|READ_CONTROL,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr));if(!file)return GetLastError()==ERROR_SHARING_VIOLATION?Ownership::owned:Ownership::unavailable;verify_security(file.value,scope.sid(),SE_FILE_OBJECT);return Ownership::free;}catch(...){return Ownership::unavailable;}}
class HostLease {
    Handle mutex_,file_;bool held_{};
public:
    explicit HostLease(const Scope& scope){scope.prepare_private_directory();UserSecurity security(scope.sid());mutex_.reset(CreateMutexW(&security.attributes,FALSE,scope.mutex().c_str()));if(!mutex_)throw std::runtime_error("Could not open the private host singleton lease");verify_security(mutex_.value,scope.sid());const auto status=WaitForSingleObject(mutex_.value,0);held_=status==WAIT_OBJECT_0||status==WAIT_ABANDONED;if(!held_)throw std::runtime_error("Another background host owns this physical data folder");try{const auto lock=scope.ledger_directory()/L"host.lock";if(local_file::reparse(lock))throw std::runtime_error("The host ownership file is linked");file_.reset(CreateFileW(lock.c_str(),GENERIC_READ|GENERIC_WRITE|READ_CONTROL,FILE_SHARE_READ,&security.attributes,OPEN_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr));if(!file_)throw std::runtime_error("Another host owns this physical runtime ledger");verify_security(file_.value,scope.sid(),SE_FILE_OBJECT);Object owner;owner.SetNamedValue(L"pid",Value::CreateNumberValue(GetCurrentProcessId()));put(owner,L"scope",scope.id());const auto bytes=winrt::to_string(owner.Stringify());DWORD copied{};if(!SetFilePointerEx(file_.value,{},nullptr,FILE_BEGIN)||!SetEndOfFile(file_.value)||!WriteFile(file_.value,bytes.data(),static_cast<DWORD>(bytes.size()),&copied,nullptr)||copied!=bytes.size()||!FlushFileBuffers(file_.value))throw std::runtime_error("Could not persist the nonsecret host ownership record");}catch(...){ReleaseMutex(mutex_.value);held_=false;throw;}}
    ~HostLease(){if(held_)ReleaseMutex(mutex_.value);}HostLease(const HostLease&)=delete;HostLease& operator=(const HostLease&)=delete;
};
struct FileIdentity {ULONGLONG volume{};std::array<BYTE,16> id{};bool operator==(const FileIdentity&)const=default;};
inline FileIdentity file_identity(const std::filesystem::path& path){Handle file(CreateFileW(path.c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr));FILE_ID_INFO info{};if(!file||!GetFileInformationByHandleEx(file.value,FileIdInfo,&info,sizeof(info)))throw std::runtime_error("Could not identify the trusted background-host executable");FileIdentity result;result.volume=info.VolumeSerialNumber;std::copy(std::begin(info.FileId.Identifier),std::end(info.FileId.Identifier),result.id.begin());return result;}
inline std::filesystem::path current_image(){std::array<wchar_t,32768> path{};const auto count=GetModuleFileNameW(nullptr,path.data(),static_cast<DWORD>(path.size()));if(!count||count>=path.size())throw std::runtime_error("Could not identify this app executable");return path.data();}
inline Handle authenticate_peer(HANDLE pipe,bool server,const Scope& scope,const FileIdentity& expected){ULONG pid{};if(!(server?GetNamedPipeClientProcessId(pipe,&pid):GetNamedPipeServerProcessId(pipe,&pid))||!pid)throw std::runtime_error("Could not identify the background-host peer");Handle process(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION|SYNCHRONIZE,FALSE,pid));DWORD own_session{},peer_session{};std::array<wchar_t,32768> path{};DWORD size=static_cast<DWORD>(path.size());if(!process||user_sid(process.value)!=scope.sid()||!ProcessIdToSessionId(GetCurrentProcessId(),&own_session)||!ProcessIdToSessionId(pid,&peer_session)||peer_session!=own_session||!QueryFullProcessImageNameW(process.value,0,path.data(),&size)||file_identity(std::filesystem::path(std::wstring(path.data(),size)))!=expected||WaitForSingleObject(process.value,0)!=WAIT_TIMEOUT)throw std::runtime_error("The background-host peer is not this trusted app and user session");return process;}
} // namespace coincide::background_host
